9	
10	import * as S from './Ad.styled';
11	import {
12	  dismissAdItemForToday,
13	  getNextAdDismissalExpiry,
14	  getSafeAdDismissalDelay,
15	  readDismissedAdItemIds,
16	} from './adDismissal';
17	import { sendAdTrackingEvent } from './adTracking';
18	import { getImageIndicatorColor, getIndicatorColorFromCssColor } from './getAdIndicatorColor';
19	import { useStrapiCatalog } from './useStrapiCatalog';
20	
21	import type { AdProps } from './Ad.types';
22	
23	const INDICATOR_BAR_HEIGHT = 4;
24	
25	const Ad = ({ className, dismissible, items = [], onVisibilityChange, slug, variant }: AdProps) => {
26	  const { query } = useRouter();
27	  const [activeIndex, setActiveIndex] = useState(0);
28	  const [dismissalState, setDismissalState] = useState<{
29	    dismissedItemIds: Set<string>;
30	    slug?: string;
31	  }>({ dismissedItemIds: new Set() });
32	  const [closeButtonColor, setCloseButtonColor] = useState('#333333');
33	  const [indicatorColor, setIndicatorColor] = useState('#333333');
34	  const [layoutVersion, setLayoutVersion] = useState(0);
35	  const adRef = useRef<HTMLDivElement>(null);
36	  const activeIndexRef = useRef(0);
37	  const closeButtonRef = useRef<HTMLButtonElement>(null);
38	  const closeButtonRequestRef = useRef(0);
39	  const indicatorColorCacheRef = useRef(new Map<string, Promise<string>>());
40	  const indicatorGroupRef = useRef<HTMLDivElement>(null);
41	  const indicatorRequestRef = useRef(0);
42	  const rollingGenerationRef = useRef(0);
43	  const rollingTimerRef = useRef<ReturnType<typeof setTimeout>>();
44	  const resumeTimerRef = useRef<ReturnType<typeof setTimeout>>();
45	  const catalog = useStrapiCatalog(slug);
46	  const resolvedItems = slug ? catalog.items : items;
47	  const isTodayDismissible = Boolean(dismissible && slug);
48	  const isDismissalReady = !isTodayDismissible || dismissalState.slug === slug;
49	  const visibleItems = isTodayDismissible
50	    ? resolvedItems.filter(
51	        (item) => item.id === undefined || !dismissalState.dismissedItemIds.has(String(item.id))
52	      )
53	    : resolvedItems;
54	  const isSlider =
55	    variant === 'banner-small' ||
56	    variant === 'banner-large' ||
57	    variant === 'banner-landing' ||
58	    variant === 'card-large' ||
59	    variant === 'card-medium' ||
60	    variant === 'card-small';
61	  const hasControls = isDismissalReady && isSlider && visibleItems.length > 1;
62	  const hasBannerIndicators = hasControls && variant.startsWith('banner');
63	  const hasTodayDismissButton =
64	    isDismissalReady &&
65	    isTodayDismissible &&
66	    visibleItems[activeIndex]?.id !== undefined &&
67	    variant.startsWith('banner');
68	  const isVisible =
69	    !(slug && (catalog.isLoading || catalog.isError)) &&
70	    isDismissalReady &&
71	    visibleItems.length > 0;
72	  const activeItem = visibleItems[activeIndex];
73	  const activeBackgroundColor = activeItem?.backgroundColor;
74	  const activeImageSrc = activeItem?.image?.src;
75	  const controlColor = activeItem?.textColor || '#333333';
76	  const indicatorBottomOffset = variant === 'banner-large' ? 8 : 4;
77	  const storeName = typeof query.storeName === 'string' ? query.storeName : undefined;
78	  // MEMO: 에디터 라우트(/editor/[storeId])에는 storeName 쿼리가 없어 그 구좌의 클릭이 전송되지 않았다.
79	  // gtmService와 같은 방식으로 로그인 사용자의 현재 스토어로 보완한다.
80	  const signedInStoreName = LocalStorage.getItem<{ currentStore?: { storeName?: string } }>('user')
81	    ?.currentStore?.storeName;
82	  const trackingUser = storeName || signedInStoreName || '';
83	
84	  const trackCatalogEvent = useCallback(
85	    (value: string) =>
86	      slug && trackingUser
87	        ? sendAdTrackingEvent({
88	            event: `ad:click:${slug}`,
89	            user: trackingUser,
90	            value,
91	          })
92	        : false,
93	    [slug, trackingUser]
94	  );
95	
96	  useEffect(() => {
97	    onVisibilityChange?.(isVisible);
98	  }, [isVisible, onVisibilityChange]);
99	
100	  useEffect(() => {
101	    if (!isTodayDismissible) {
102	      setActiveIndex(0);
103	      activeIndexRef.current = 0;
104	      return;
105	    }
106	
107	    if (visibleItems.length === 0 || activeIndexRef.current < visibleItems.length) {
108	      return;
109	    }
110	
111	    const nextIndex = visibleItems.length - 1;
112	    activeIndexRef.current = nextIndex;
113	    setActiveIndex(nextIndex);
114	  }, [isTodayDismissible, slug, visibleItems.length]);
115	
116	  useEffect(() => {
117	    if (!isTodayDismissible || !slug) {
118	      setDismissalState({ dismissedItemIds: new Set() });
119	      return;
120	    }
121	
122	    setDismissalState({
123	      dismissedItemIds: new Set(readDismissedAdItemIds(window.localStorage, slug, new Date())),
124	      slug,
125	    });
126	  }, [isTodayDismissible, slug]);
127	
128	  useEffect(() => {
129	    if (!isTodayDismissible || !slug || dismissalState.slug !== slug) {
130	      return undefined;
131	    }
132	
133	    const now = new Date();
134	    const nextExpiry = getNextAdDismissalExpiry(window.localStorage, slug, now);
135	
136	    if (nextExpiry === undefined) {
137	      return undefined;
138	    }
139	
140	    const expiryTimer = setTimeout(() => {
141	      setDismissalState({
142	        dismissedItemIds: new Set(readDismissedAdItemIds(window.localStorage, slug, new Date())),
143	        slug,
144	      });
145	    }, getSafeAdDismissalDelay(nextExpiry, now));
146	
147	    return () => clearTimeout(expiryTimer);
148	  }, [dismissalState.dismissedItemIds, dismissalState.slug, isTodayDismissible, slug]);
149	
150	  const moveTo = useCallback(
151	    (index: number) => {
152	      if (visibleItems.length === 0) {
153	        return;
154	      }
155	
156	      const nextIndex = (index + visibleItems.length) % visibleItems.length;
157	      activeIndexRef.current = nextIndex;
158	      setActiveIndex(nextIndex);
159	    },
160	    [visibleItems.length]
161	  );
162	
163	  const startRolling = useCallback(() => {
164	    const generation = rollingGenerationRef.current + 1;
165	    rollingGenerationRef.current = generation;
166	    clearTimeout(rollingTimerRef.current);
167	    rollingTimerRef.current = setTimeout(() => {
168	      if (rollingGenerationRef.current !== generation) {
169	        return;
170	      }
171	
172	      moveTo(activeIndexRef.current + 1);
173	      startRolling();
174	    }, 3000);
175	  }, [moveTo]);
176	
177	  useEffect(() => {
178	    if (!hasControls) {
179	      clearTimeout(resumeTimerRef.current);
180	      return undefined;
181	    }
182	
183	    startRolling();
184	
185	    return () => {
186	      rollingGenerationRef.current += 1;
187	      clearTimeout(rollingTimerRef.current);
188	      clearTimeout(resumeTimerRef.current);
189	    };
190	  }, [hasControls, startRolling]);
191	
192	  useEffect(
193	    () => () => {
194	      rollingGenerationRef.current += 1;
195	      clearTimeout(rollingTimerRef.current);
196	      clearTimeout(resumeTimerRef.current);
197	    },
198	    []
199	  );
200	
201	  useEffect(() => {
202	    if (
203	      (!hasBannerIndicators && !hasTodayDismissButton) ||
204	      !adRef.current ||
205	      typeof ResizeObserver === 'undefined'
206	    ) {
207	      return undefined;
208	    }
209	
210	    const resizeObserver = new ResizeObserver(() => setLayoutVersion((version) => version + 1));
211	    resizeObserver.observe(adRef.current);
212	
213	    return () => resizeObserver.disconnect();
214	  }, [hasBannerIndicators, hasTodayDismissButton]);
215	
216	  useEffect(() => {
217	    const requestId = indicatorRequestRef.current + 1;
218	    indicatorRequestRef.current = requestId;
219	    setIndicatorColor(controlColor);
220	
221	    if (!hasBannerIndicators) {
222	      return;
223	    }
224	
225	    if (!activeImageSrc) {
226	      setIndicatorColor(
227	        getIndicatorColorFromCssColor(
228	          activeBackgroundColor || '#ffffff',
229	          controlColor,
230	          variant === 'banner-small' ? 0.1 : 0
231	        )
232	      );
233	      return;
234	    }
235	
236	    const adRect = adRef.current?.getBoundingClientRect();
237	    const indicatorRect = indicatorGroupRef.current?.getBoundingClientRect();
238	
239	    if (!adRect || !indicatorRect) {
240	      return;
241	    }
242	
243	    const imageIndicatorColorParams = {
244	      backgroundColor: activeBackgroundColor,
245	      containerHeight: adRect.height,
246	      containerWidth: adRect.width,
247	      indicatorHeight: INDICATOR_BAR_HEIGHT,
248	      indicatorLeft: indicatorRect.left - adRect.left,
249	      indicatorTop: Math.max(
250	        0,
251	        indicatorRect.bottom - adRect.top - indicatorBottomOffset - INDICATOR_BAR_HEIGHT
252	      ),
253	      indicatorWidth: indicatorRect.width,
254	      overlayOpacity: variant === 'banner-small' ? 0.1 : 0,
255	      src: activeImageSrc,
256	    };
257	    const cacheKey = JSON.stringify(imageIndicatorColorParams);
258	    const cachedColorRequest = indicatorColorCacheRef.current.get(cacheKey);
259	    const colorRequest = cachedColorRequest || getImageIndicatorColor(imageIndicatorColorParams);
260	
261	    if (!cachedColorRequest) {
262	      indicatorColorCacheRef.current.set(cacheKey, colorRequest);
263	    }
264	
265	    let cancelled = false;
266	
267	    void colorRequest
268	      .then((color) => {
269	        if (!cancelled && indicatorRequestRef.current === requestId) {
270	          setIndicatorColor(color);
271	        }
272	      })
273	      .catch(() => indicatorColorCacheRef.current.delete(cacheKey));
274	
275	    return () => {
276	      cancelled = true;
277	    };
278	  }, [
279	    activeBackgroundColor,
280	    activeImageSrc,
281	    controlColor,
282	    hasBannerIndicators,
283	    indicatorBottomOffset,
284	    layoutVersion,
285	    variant,
286	  ]);
287	
288	  useEffect(() => {
289	    const requestId = closeButtonRequestRef.current + 1;
290	    closeButtonRequestRef.current = requestId;
291	    setCloseButtonColor(controlColor);
292	
293	    if (!hasTodayDismissButton) {
294	      return;
295	    }
296	
297	    if (!activeImageSrc) {
298	      setCloseButtonColor(
299	        getIndicatorColorFromCssColor(
300	          activeBackgroundColor || '#ffffff',
301	          controlColor,
302	          variant === 'banner-small' ? 0.1 : 0
303	        )
304	      );
305	      return;
306	    }
307	
308	    const adRect = adRef.current?.getBoundingClientRect();
309	    const closeButtonRect = closeButtonRef.current?.getBoundingClientRect();
310	
311	    if (!adRect || !closeButtonRect) {
312	      return;
313	    }
314	
315	    const imageColorParams = {
316	      backgroundColor: activeBackgroundColor,
317	      containerHeight: adRect.height,
318	      containerWidth: adRect.width,
319	      indicatorHeight: closeButtonRect.height,
320	      indicatorLeft: closeButtonRect.left - adRect.left,
321	      indicatorTop: closeButtonRect.top - adRect.top,
322	      indicatorWidth: closeButtonRect.width,
323	      overlayOpacity: variant === 'banner-small' ? 0.1 : 0,
324	      src: activeImageSrc,
325	    };
326	    const cacheKey = JSON.stringify(imageColorParams);
327	    const cachedColorRequest = indicatorColorCacheRef.current.get(cacheKey);
328	    const colorRequest = cachedColorRequest || getImageIndicatorColor(imageColorParams);
329	
330	    if (!cachedColorRequest) {
331	      indicatorColorCacheRef.current.set(cacheKey, colorRequest);
332	    }
333	
334	    let cancelled = false;
335	
336	    void colorRequest
337	      .then((color) => {
338	        if (!cancelled && closeButtonRequestRef.current === requestId) {
339	          setCloseButtonColor(color);
340	        }
341	      })
342	      .catch(() => indicatorColorCacheRef.current.delete(cacheKey));
343	
344	    return () => {
345	      cancelled = true;
346	    };
347	  }, [
348	    activeBackgroundColor,
349	    activeImageSrc,
350	    controlColor,
351	    hasTodayDismissButton,
352	    layoutVersion,
353	    variant,
354	  ]);
355	
356	  const handleManualMove = (index: number) => {
357	    moveTo(index);
358	    rollingGenerationRef.current += 1;
359	    const generation = rollingGenerationRef.current;
360	    clearTimeout(rollingTimerRef.current);
361	    clearTimeout(resumeTimerRef.current);
362	    resumeTimerRef.current = setTimeout(() => {
363	      if (rollingGenerationRef.current !== generation) {
364	        return;
365	      }
366	
367	      moveTo(activeIndexRef.current + 1);
368	      startRolling();
369	    }, 5000);
370	  };
371	
372	  const handleDismissForToday = () => {
373	    if (!slug || activeItem?.id === undefined) {
374	      return;
375	    }
376	
377	    if (!dismissAdItemForToday(window.localStorage, slug, activeItem.id, new Date())) {
378	      return;
379	    }
380	
381	    clearTimeout(rollingTimerRef.current);
382	    clearTimeout(resumeTimerRef.current);
383	    rollingGenerationRef.current += 1;
384	
385	    const nextVisibleItemCount = visibleItems.length - 1;
386	    const nextIndex = nextVisibleItemCount === 0 ? 0 : activeIndex % nextVisibleItemCount;
387	    activeIndexRef.current = nextIndex;
388	    setActiveIndex(nextIndex);
389	    setDismissalState((current) => ({
390	      dismissedItemIds: new Set([...current.dismissedItemIds, String(activeItem.id)]),
391	      slug,
392	    }));
393	  };
394	
395	  if (!isVisible) {
396	    return null;
397	  }
398	
399	  return (
400	    <S.Ad ref={adRef} className={className} $variant={variant} data-testid={`ad-${variant}`}>
401	      <S.Track
402	        data-testid={`ad-track-${variant}`}
403	        style={{ transform: `translateX(-${activeIndex * 100}%)` }}
404	      >
405	        {visibleItems.map((item, index) => {
406	          const isLinked = Boolean(item.href);
407	
408	          const handleClick = () => {
409	            if (isLinked && item.id !== undefined) {
410	              trackCatalogEvent(String(item.title ?? ''));
411	            }
412	          };
413	
414	          return (
415	            <S.Slide
416	              as={isLinked ? 'a' : 'div'}
417	              href={isLinked ? item.href : undefined}
418	              onClick={isLinked ? handleClick : undefined}
419	              rel={isLinked ? 'noopener noreferrer' : undefined}
420	              target={isLinked ? '_blank' : undefined}
421	              key={`${variant}-${index}`}
422	              $backgroundColor={item.backgroundColor}
423	              $textColor={item.textColor}
424	              $variant={variant}
425	            >
426	              {item.image && (variant.startsWith('banner') || variant.startsWith('card')) && (
427	                <S.Image
428	                  src={item.image.src}
429	                  alt={item.image.alt}
430	                  data-testid={`ad-image-${variant}`}
431	                  $variant={variant}
432	                />
433	              )}
434	              {!item.image && (
435	                <S.Content $variant={variant}>
436	                  <S.Title $variant={variant}>{item.title}</S.Title>
437	                  {item.body && <S.Body $variant={variant}>{item.body}</S.Body>}
438	                </S.Content>
439	              )}
440	            </S.Slide>
441	          );
442	        })}
443	      </S.Track>
444	      {hasControls && variant.startsWith('card') && (
445	        <S.CardCarouselNav data-testid={`ad-card-nav-${variant}`}>
446	          <S.CardArrowButton
447	            aria-label='이전 광고'
448	            type='button'
449	            onClick={() => handleManualMove(activeIndex - 1)}
450	          >
451	            <Icon name='chevron' size={20} color='white' direction='left' />
452	          </S.CardArrowButton>
453	          <S.CardArrowButton
454	            aria-label='다음 광고'
455	            type='button'
456	            onClick={() => handleManualMove(activeIndex + 1)}
457	          >
458	            <Icon name='chevron' size={20} color='white' direction='right' />
459	          </S.CardArrowButton>
460	        </S.CardCarouselNav>
461	      )}
462	      {hasBannerIndicators && (
463	        <S.IndicatorGroup
464	          ref={indicatorGroupRef}
465	          $variant={variant}
466	          data-testid={`ad-indicators-${variant}`}
467	        >
468	          {visibleItems.map((_, index) => {
469	            const isActive = index === activeIndex;
470	
471	            return (
472	              <S.IndicatorButton
473	                aria-current={isActive ? 'true' : undefined}
474	                aria-label={`${index + 1}번째 광고`}
475	                key={`${variant}-indicator-${index}`}
476	                onClick={() => handleManualMove(index)}
477	                type='button'
478	                $active={isActive}
479	                $color={indicatorColor}
480	                $variant={variant}
481	              />
482	            );
483	          })}
484	        </S.IndicatorGroup>
485	      )}
486	      {hasTodayDismissButton && (
487	        <Tooltip label='오늘 하루 보지 않기' placement='top'>
488	          <S.CloseButton
489	            ref={closeButtonRef}
490	            aria-label='오늘 하루 보지 않기'
491	            onClick={handleDismissForToday}
492	            type='button'
493	          >
494	            <Icon name='cancelSmall' size={20} color={closeButtonColor} />
495	          </S.CloseButton>
496	        </Tooltip>
497	      )}
498	    </S.Ad>
499	  );
500	};
501	
502	export default Ad;
